import SwiftUI

struct CoursesView:View{
 @Environment(\.dismiss)var dismiss;@Environment(CourseStore.self)var store;@State var create=false
 var body:some View{NavigationStack{ZStack{CourseBG();ScrollView{VStack(spacing:16){header;if store.courses.isEmpty{empty}else{ForEach(store.courses){c in NavigationLink{CourseEditor(course:c)}label:{courseCard(c)}.buttonStyle(.plain)}}}.padding(16)}}.navigationTitle("Мои курсы").navigationBarTitleDisplayMode(.inline).toolbar{ToolbarItem(placement:.cancellationAction){Button("Закрыть"){dismiss()}};ToolbarItem(placement:.primaryAction){Button{create=true}label:{Image(systemName:"plus.circle.fill").font(.title2)}}}.sheet(isPresented:$create){NewCourseSheet()}}}
 private var header:some View{VStack(alignment:.leading,spacing:6){Text("КУРС — ЭТО СТРУКТУРА ЗНАНИЙ").font(.caption.bold()).foregroundStyle(.cyan);Text("Разделы → темы → опросники").font(.title2.bold()).foregroundStyle(.white);Text("Собери содержание. Цели и порядок обучения добавим отдельно после проверки модели курса.").font(.caption).foregroundStyle(.white.opacity(0.6))}.frame(maxWidth:.infinity,alignment:.leading).padding(16).card()}
 private var empty:some View{Button{create=true}label:{VStack(spacing:12){Image(systemName:"graduationcap.fill").font(.system(size:40));Text("Создать курс").font(.headline);Text("Название, описание и содержание").font(.caption).opacity(0.65)}.frame(maxWidth:.infinity).padding(.vertical,40)}.buttonStyle(.borderedProminent).tint(.cyan.opacity(0.25)).foregroundStyle(.white)}
 private func courseCard(_ c:StudyCourse)->some View{HStack(spacing:14){Image(systemName:c.coverSymbol).font(.title).foregroundStyle(.cyan).frame(width:44);VStack(alignment:.leading,spacing:5){Text(c.title).font(.headline);if !c.subject.isEmpty{Text([c.subject,c.audience].filter{!$0.isEmpty}.joined(separator:" · ")).font(.caption).foregroundStyle(.cyan)};Text("\(c.sections.count) разделов · \(c.topicCount) тем · \(c.questionSetCount) опросников").font(.caption2).foregroundStyle(.white.opacity(0.55))};Spacer();Image(systemName:"chevron.right")}.foregroundStyle(.white).padding(15).card()}
}

private struct NewCourseSheet:View{@Environment(\.dismiss)var dismiss;@Environment(CourseStore.self)var store;@State var title="";@State var description="";@State var subject="";@State var audience="";@State var hours="";@State var language="Русский";var body:some View{NavigationStack{ZStack{CourseBG();ScrollView{VStack(spacing:15){field("НАЗВАНИЕ *","ЕГЭ Химия 2027",$title);field("ОПИСАНИЕ","Что даст этот курс и что в него входит",$description);field("ПРЕДМЕТ / КАТЕГОРИЯ","Химия",$subject);field("ДЛЯ КОГО","10–11 класс · ЕГЭ",$audience);field("ПРИМЕРНОЕ ВРЕМЯ, ЧАСОВ","Например: 20",$hours,.decimalPad);field("ЯЗЫК","Русский",$language)}.padding(18)}}.navigationTitle("Новый курс").toolbar{ToolbarItem(placement:.cancellationAction){Button("Отмена"){dismiss()}};ToolbarItem(placement:.confirmationAction){Button("Создать"){_ = store.create(title:title.trim,description:description.trim,subject:subject.trim,audience:audience.trim,minutes:duration,language:language.trim);dismiss()}.disabled(title.trim.isEmpty)}}}}
 private var duration:Int?{Double(hours.replacingOccurrences(of:",",with:".")).map{Int($0*60)}}
}

private struct CourseEditor:View{
 @Environment(CourseStore.self)var store;@State var course:StudyCourse;@State var preview=false;@State var addSection=false;@State var editInfo=false;@State var tab=0;@State var addGoal=false
 var body:some View{ZStack{CourseBG();ScrollView{VStack(spacing:15){summary;Picker("Режим",selection:$tab){Text("Содержание").tag(0);Text("Цели").tag(1)}.pickerStyle(.segmented);if tab==0{ForEach(Array(course.sections.enumerated()),id:\.element.id){i,_ in sectionCard(i)};if course.sections.count > 1 { NavigationLink{SectionOrderView(sections:$course.sections,onChange:save)}label:{Label("Изменить порядок разделов",systemImage:"arrow.up.arrow.down").frame(maxWidth:.infinity).padding(10)}.buttonStyle(.bordered).tint(.cyan) };Button{addSection=true}label:{Label("Добавить раздел",systemImage:"plus.circle.fill").frame(maxWidth:.infinity).padding(10)}.buttonStyle(.borderedProminent).tint(.cyan.opacity(0.28))}else{goalsView}}.padding(16)}}.navigationTitle(course.title).navigationBarTitleDisplayMode(.inline).toolbar{ToolbarItemGroup(placement:.primaryAction){Button{preview=true}label:{Image(systemName:"eye")};Button{editInfo=true}label:{Image(systemName:"pencil")}}}.sheet(isPresented:$addSection){SectionSheet{course.sections.append($0);save()}}.sheet(isPresented:$editInfo){CourseInfoSheet(course:$course,onSave:save)}.sheet(isPresented:$preview){CoursePreview(course:course)}.sheet(isPresented:$addGoal){GoalSheet(course:course){course.goals.append($0);save()}} }
 private var summary:some View{VStack(alignment:.leading,spacing:8){HStack{Image(systemName:course.coverSymbol).font(.title).foregroundStyle(.cyan);VStack(alignment:.leading){Text(course.title).font(.title3.bold());Text([course.subject,course.audience].filter{!$0.isEmpty}.joined(separator:" · ")).font(.caption).foregroundStyle(.cyan)}};if !course.description.isEmpty{Text(course.description).font(.subheadline).foregroundStyle(.white.opacity(0.7))};HStack{Label("\(course.sections.count) разделов",systemImage:"list.bullet.rectangle");Label("\(course.topicCount) тем",systemImage:"square.grid.2x2");if let m=course.estimatedMinutes{Label(time(m),systemImage:"clock")}}.font(.caption).foregroundStyle(.white.opacity(0.55));Text("Нажми ✎ сверху, чтобы изменить описание и параметры курса.").font(.caption2).foregroundStyle(.cyan.opacity(0.75))}.foregroundStyle(.white).frame(maxWidth:.infinity,alignment:.leading).padding(16).card()}
 private func sectionCard(_ i:Int)->some View{let s=course.sections[i];return VStack(alignment:.leading,spacing:10){NavigationLink{SectionEditor(section:$course.sections[i],onChange:save)}label:{HStack(alignment:.top){Text(String(format:"%02d",i+1)).font(.headline).foregroundStyle(.black).frame(width:34,height:34).background(.cyan,in:Circle());VStack(alignment:.leading,spacing:4){Text(s.title).font(.headline);if !s.description.isEmpty{Text(s.description).font(.caption).foregroundStyle(.white.opacity(0.58)).lineLimit(2)};HStack{Text("\(s.topics.count) тем");if let m=s.estimatedMinutes{Text("· ~\(time(m))")}}.font(.caption2).foregroundStyle(.cyan)};Spacer();Image(systemName:"chevron.right")}.foregroundStyle(.white)};ForEach(s.topics){t in HStack{Rectangle().fill(.cyan.opacity(0.25)).frame(width:2,height:28);VStack(alignment:.leading){Text(t.title).font(.subheadline.bold());Text("\(t.questionSets.count) опросников").font(.caption2).foregroundStyle(.white.opacity(0.5))};Spacer()}.padding(.leading,16).foregroundStyle(.white)}}.padding(14).card()}
 private var goalsView:some View{VStack(spacing:12){VStack(alignment:.leading,spacing:6){Text("УЧЕБНЫЕ ЦЕЛИ").font(.caption.bold()).foregroundStyle(.cyan);Text("Цель задаёт результат. Общее время занятий задаётся отдельно и распределяется между всеми активными целями.").font(.caption).foregroundStyle(.white.opacity(0.6))}.frame(maxWidth:.infinity,alignment:.leading).padding(14).card();if course.goals.isEmpty{Text("Пока нет целей. Добавь первую цель и выбери, какие опросники нужно освоить.").foregroundStyle(.white.opacity(0.6)).frame(maxWidth:.infinity,alignment:.leading).padding(16).card()}else{ForEach(course.goals){g in VStack(alignment:.leading,spacing:7){HStack{Text(g.title).font(.headline);Spacer();Text("\(g.masteryTarget)%").font(.headline).foregroundStyle(.cyan)};Text("\(g.questionSets.count) опросников"+(g.deadline.map{" · до \($0.formatted(date:.abbreviated,time:.omitted))"} ?? "")).font(.caption).foregroundStyle(.white.opacity(0.55));Text(g.state == .active ? "Активная":"Запланирована").font(.caption2.bold()).foregroundStyle(g.state == .active ? .mint:.cyan)}.foregroundStyle(.white).frame(maxWidth:.infinity,alignment:.leading).padding(14).card()}};Button{addGoal=true}label:{Label("Добавить цель",systemImage:"target").frame(maxWidth:.infinity).padding(10)}.buttonStyle(.borderedProminent).tint(.cyan.opacity(0.28))}}
 private func save(){store.save(course)}
}
private struct SectionEditor:View{@Binding var section:CourseSection;let onChange:()->Void;@State var addTopic=false;@State var edit=false;var body:some View{ZStack{CourseBG();ScrollView{VStack(alignment:.leading,spacing:14){VStack(alignment:.leading,spacing:7){Text(section.title).font(.title2.bold());if !section.description.isEmpty{Text(section.description).foregroundStyle(.white.opacity(0.68))};if let m=section.estimatedMinutes{Label("Примерно \(time(m))",systemImage:"clock").font(.caption).foregroundStyle(.cyan)}}.foregroundStyle(.white).frame(maxWidth:.infinity,alignment:.leading).padding(16).card();Text("ТЕМЫ").font(.caption.bold()).foregroundStyle(.cyan);ForEach(Array(section.topics.enumerated()),id:\.element.id){i,_ in NavigationLink{TopicEditor(topic:$section.topics[i],onChange:onChange)}label:{HStack{Text("\(i+1)").font(.headline).foregroundStyle(.cyan).frame(width:28);VStack(alignment:.leading){Text(section.topics[i].title).font(.headline);Text("\(section.topics[i].questionSets.count) опросников").font(.caption).foregroundStyle(.white.opacity(0.5))};Spacer();Image(systemName:"chevron.right")}.foregroundStyle(.white).padding(14).card()}};if section.topics.count > 1 { NavigationLink{TopicOrderView(topics:$section.topics,onChange:onChange)}label:{Label("Изменить порядок тем",systemImage:"arrow.up.arrow.down").frame(maxWidth:.infinity).padding(10)}.buttonStyle(.bordered).tint(.cyan) };Button{addTopic=true}label:{Label("Добавить тему",systemImage:"plus.circle.fill").frame(maxWidth:.infinity).padding(10)}.buttonStyle(.borderedProminent).tint(.cyan.opacity(0.28))}.padding(16)}}.navigationTitle("Раздел").toolbar{Button{edit=true}label:{Image(systemName:"pencil")}}.sheet(isPresented:$addTopic){NameSheet(title:"Новая тема",placeholder:"Например: Кислоты"){section.topics.append(.init(id:UUID(),title:$0,questionSets:[]));onChange()}}.sheet(isPresented:$edit){SectionEditSheet(section:$section,onSave:onChange)}}}
private struct TopicEditor:View{@Environment(MaterialStore.self)var materials;@Binding var topic:CourseTopic;let onChange:()->Void;@State var choose=false;@State var rename=false;var body:some View{ZStack{CourseBG();ScrollView{VStack(alignment:.leading,spacing:14){VStack(alignment:.leading,spacing:5){Text("ТЕМА").font(.caption.bold()).foregroundStyle(.cyan);Text(topic.title).font(.title2.bold()).foregroundStyle(.white);Text("Опросник — конкретный набор вопросов внутри материала.").font(.caption).foregroundStyle(.white.opacity(0.55))}.frame(maxWidth:.infinity,alignment:.leading).padding(16).card();Text("ОПРОСНИКИ").font(.caption.bold()).foregroundStyle(.cyan);if topic.questionSets.isEmpty{Text("Ничего не привязано. Выбери один или несколько наборов вопросов из своей библиотеки.").foregroundStyle(.white.opacity(0.6)).padding(16).card()}else{ForEach(topic.questionSets,id:\.self){ref in if let info=ruleInfo(ref,materials){HStack{Image(systemName:"questionmark.bubble.fill").foregroundStyle(.mint);VStack(alignment:.leading){Text(info.0).font(.headline);Text(info.1).font(.caption).foregroundStyle(.cyan)};Spacer()}.foregroundStyle(.white).padding(14).card()}}};Button{choose=true}label:{Label(topic.questionSets.isEmpty ? "Выбрать опросники":"Изменить опросники",systemImage:"checklist").frame(maxWidth:.infinity).padding(10)}.buttonStyle(.borderedProminent).tint(.cyan.opacity(0.28))}.padding(16)}}.navigationTitle(topic.title).toolbar{Button{rename=true}label:{Image(systemName:"pencil")}}.sheet(isPresented:$choose,onDismiss:onChange){RulePicker(selected:$topic.questionSets)}.sheet(isPresented:$rename){NameSheet(title:"Название темы",placeholder:"Название"){topic.title=$0;onChange()}}}}
private struct RulePicker:View{@Environment(MaterialStore.self)var materials;@Environment(\.dismiss)var dismiss;@Binding var selected:[CourseRuleReference];var body:some View{NavigationStack{ZStack{CourseBG();ScrollView{LazyVStack(spacing:12){ForEach(materials.materials){m in if let c=materials.content(id:m.id),!c.rules.filter(\.enabled).isEmpty{VStack(alignment:.leading,spacing:9){Text(m.title).font(.headline).foregroundStyle(.white);Text("Наборы вопросов этого материала").font(.caption).foregroundStyle(.white.opacity(0.5));ForEach(c.rules.filter(\.enabled)){r in let ref=CourseRuleReference(materialID:m.id,ruleID:r.id);Button{toggle(ref)}label:{HStack{Image(systemName:selected.contains(ref) ? "checkmark.circle.fill":"circle").foregroundStyle(selected.contains(ref) ? .cyan:.white.opacity(0.35));VStack(alignment:.leading,spacing:2){Text(ruleName(r,c)).foregroundStyle(.white);Text("\(c.rows.count) вопросов").font(.caption2).foregroundStyle(.white.opacity(0.45))};Spacer()}.padding(11).background(.black.opacity(0.22),in:RoundedRectangle(cornerRadius:12))}.buttonStyle(.plain)}}.padding(14).card()}}}.padding(16)}}.navigationTitle("Выбрать опросники").toolbar{Button("Готово"){dismiss()}}}};private func toggle(_ x:CourseRuleReference){if let i=selected.firstIndex(of:x){selected.remove(at:i)}else{selected.append(x)}}}

private struct GoalSheet:View{@Environment(\.dismiss)var dismiss;let course:StudyCourse;let save:(LearningGoal)->Void;@State var title="";@State var mastery=90.0;@State var hasDeadline=true;@State var deadline=Calendar.current.date(byAdding:.day,value:15,to:Date()) ?? Date();@State var selected:[CourseRuleReference]=[];@State var choose=false;var body:some View{NavigationStack{ZStack{CourseBG();ScrollView{VStack(spacing:16){field("НАЗВАНИЕ *","Например: Выучить кислоты",$title);VStack(alignment:.leading,spacing:10){Text("РЕЗУЛЬТАТ").font(.caption.bold()).foregroundStyle(.cyan);HStack{Text("Освоить");Spacer();Text("\(Int(mastery))%").foregroundStyle(.cyan).font(.headline)}.foregroundStyle(.white);Slider(value:$mastery,in:50...100,step:5).tint(.cyan)}.padding(14).card();VStack(alignment:.leading,spacing:10){Toggle("Срок",isOn:$hasDeadline).tint(.cyan).foregroundStyle(.white);if hasDeadline{DatePicker("Завершить до",selection:$deadline,in:Date()...,displayedComponents:.date).tint(.cyan).foregroundStyle(.white)}}.padding(14).card();VStack(alignment:.leading,spacing:8){Text("ЧТО ОСВОИТЬ").font(.caption.bold()).foregroundStyle(.cyan);Text(selected.isEmpty ? "Опросники не выбраны":"Выбрано: \(selected.count)").foregroundStyle(.white);Button{choose=true}label:{Label("Выбрать из курса",systemImage:"checklist").frame(maxWidth:.infinity)}}.padding(14).card();Text("Время занятий не задаётся этой цели: дневной бюджет общий для всех целей. BOTAI будет распределять его по графику.").font(.caption).foregroundStyle(.white.opacity(0.55)).padding(.horizontal,4)}.padding(18)}}.navigationTitle("Новая цель").toolbar{ToolbarItem(placement:.cancellationAction){Button("Отмена"){dismiss()}};ToolbarItem(placement:.confirmationAction){Button("Создать"){save(.init(id:UUID(),title:title.trim,questionSets:selected,masteryTarget:Int(mastery),deadline:hasDeadline ? deadline:nil,state:.planned));dismiss()}.disabled(title.trim.isEmpty || selected.isEmpty)}}.sheet(isPresented:$choose){CourseRulePicker(course:course,selected:$selected)}}}}
private struct CourseRulePicker:View{@Environment(\.dismiss)var dismiss;let course:StudyCourse;@Binding var selected:[CourseRuleReference];var body:some View{NavigationStack{ZStack{CourseBG();ScrollView{VStack(spacing:12){ForEach(course.sections){section in VStack(alignment:.leading,spacing:10){Text(section.title).font(.headline).foregroundStyle(.cyan);ForEach(section.topics){topic in VStack(alignment:.leading,spacing:7){Text(topic.title).font(.subheadline.bold()).foregroundStyle(.white);ForEach(topic.questionSets,id:\.self){ref in Button{if let i=selected.firstIndex(of:ref){selected.remove(at:i)}else{selected.append(ref)}}label:{HStack{Image(systemName:selected.contains(ref) ? "checkmark.circle.fill":"circle");Text("Опросник");Spacer()}.foregroundStyle(selected.contains(ref) ? .cyan:.white.opacity(0.7)).padding(9).background(.black.opacity(0.2),in:RoundedRectangle(cornerRadius:10))}.buttonStyle(.plain)}}}.padding(12).card()}}}.padding(16)}}.navigationTitle("Содержание цели").toolbar{Button("Готово"){dismiss()}}}}}
private struct CourseInfoSheet:View{@Environment(\.dismiss)var dismiss;@Binding var course:StudyCourse;let onSave:()->Void;@State var hours="";var body:some View{NavigationStack{ZStack{CourseBG();ScrollView{VStack(spacing:14){field("НАЗВАНИЕ *","Название",$course.title);field("ОПИСАНИЕ","О курсе",$course.description);field("ПРЕДМЕТ / КАТЕГОРИЯ","Химия",$course.subject);field("ДЛЯ КОГО","10–11 класс · ЕГЭ",$course.audience);field("ПРИМЕРНОЕ ВРЕМЯ, ЧАСОВ","20",$hours,.decimalPad);field("ЯЗЫК","Русский",$course.language)}.padding(18)}}.navigationTitle("О курсе").onAppear{if let m=course.estimatedMinutes{hours=String(format:"%.1f",Double(m)/60)}}.toolbar{ToolbarItem(placement:.cancellationAction){Button("Отмена"){dismiss()}};ToolbarItem(placement:.confirmationAction){Button("Сохранить"){course.estimatedMinutes=Double(hours.replacingOccurrences(of:",",with:".")).map{Int($0*60)};onSave();dismiss()}.disabled(course.title.trim.isEmpty)}}}}}
private struct SectionSheet:View{@Environment(\.dismiss)var dismiss;let save:(CourseSection)->Void;@State var title="";@State var description="";@State var hours="";var body:some View{NavigationStack{ZStack{CourseBG();VStack(spacing:14){field("НАЗВАНИЕ РАЗДЕЛА *","Неорганическая химия",$title);field("ОПИСАНИЕ","Что входит в раздел",$description);field("ПРИМЕРНОЕ ВРЕМЯ, ЧАСОВ","5",$hours,.decimalPad);Spacer()}.padding(18)}.navigationTitle("Новый раздел").toolbar{ToolbarItem(placement:.cancellationAction){Button("Отмена"){dismiss()}};ToolbarItem(placement:.confirmationAction){Button("Добавить"){save(.init(id:UUID(),title:title.trim,description:description.trim,estimatedMinutes:Double(hours.replacingOccurrences(of:",",with:".")).map{Int($0*60)},topics:[]));dismiss()}.disabled(title.trim.isEmpty)}}}}}
private struct SectionEditSheet:View{@Environment(\.dismiss)var dismiss;@Binding var section:CourseSection;let onSave:()->Void;@State var hours="";var body:some View{NavigationStack{ZStack{CourseBG();VStack(spacing:14){field("НАЗВАНИЕ *","Название",$section.title);field("ОПИСАНИЕ","Что входит в раздел",$section.description);field("ПРИМЕРНОЕ ВРЕМЯ, ЧАСОВ","5",$hours,.decimalPad);Spacer()}.padding(18)}.navigationTitle("Раздел").onAppear{if let m=section.estimatedMinutes{hours=String(format:"%.1f",Double(m)/60)}}.toolbar{ToolbarItem(placement:.cancellationAction){Button("Отмена"){dismiss()}};ToolbarItem(placement:.confirmationAction){Button("Сохранить"){section.estimatedMinutes=Double(hours.replacingOccurrences(of:",",with:".")).map{Int($0*60)};onSave();dismiss()}.disabled(section.title.trim.isEmpty)}}}}}
private struct CoursePreview:View{@Environment(\.dismiss)var dismiss;let course:StudyCourse;var body:some View{NavigationStack{ZStack{CourseBG();ScrollView{VStack(alignment:.leading,spacing:18){ZStack{RoundedRectangle(cornerRadius:24).fill(.cyan.opacity(0.12)).frame(height:160);Image(systemName:course.coverSymbol).font(.system(size:60)).foregroundStyle(.cyan)};Text(course.title).font(.largeTitle.bold()).foregroundStyle(.white);if !course.description.isEmpty{Text(course.description).foregroundStyle(.white.opacity(0.72))};Text([course.subject,course.audience].filter{!$0.isEmpty}.joined(separator:" · ")).font(.subheadline.bold()).foregroundStyle(.cyan);HStack{Label(course.author ?? "Автор не указан",systemImage:"person.crop.circle");if let m=course.estimatedMinutes{Label("примерно \(time(m))",systemImage:"clock")}}.font(.caption).foregroundStyle(.white.opacity(0.6));Text("\(course.sections.count) разделов · \(course.topicCount) тем · \(course.questionSetCount) опросников").font(.caption).foregroundStyle(.white.opacity(0.55));Text("СОДЕРЖАНИЕ").font(.caption.bold()).foregroundStyle(.cyan);ForEach(Array(course.sections.enumerated()),id:\.element.id){i,s in VStack(alignment:.leading,spacing:6){Text("\(i+1). \(s.title)").font(.headline);if !s.description.isEmpty{Text(s.description).font(.caption).foregroundStyle(.white.opacity(0.6))};HStack{Text("\(s.topics.count) тем");if let m=s.estimatedMinutes{Text("· ~\(time(m))")}}.font(.caption2).foregroundStyle(.cyan);ForEach(s.topics){t in Text("• \(t.title) · \(t.questionSets.count) опросников").font(.subheadline).foregroundStyle(.white.opacity(0.8))}}.foregroundStyle(.white).padding(14).card()}}.padding(18)}}.navigationTitle("Предпросмотр").toolbar{Button("Готово"){dismiss()}}}}}
private struct NameSheet:View{@Environment(\.dismiss)var dismiss;let title:String,placeholder:String;let save:(String)->Void;@State var value="";var body:some View{NavigationStack{ZStack{CourseBG();VStack{field("НАЗВАНИЕ *",placeholder,$value);Spacer()}.padding(18)}.navigationTitle(title).toolbar{ToolbarItem(placement:.cancellationAction){Button("Отмена"){dismiss()}};ToolbarItem(placement:.confirmationAction){Button("Сохранить"){save(value.trim);dismiss()}.disabled(value.trim.isEmpty)}}}}}
private func field(_ label:String,_ placeholder:String,_ value:Binding<String>,_ keyboard:UIKeyboardType = .default)->some View{VStack(alignment:.leading,spacing:6){Text(label).font(.caption.bold()).foregroundStyle(.cyan);TextField(placeholder,text:value,axis:.vertical).keyboardType(keyboard).foregroundStyle(.white).padding(13).background(.black.opacity(0.28),in:RoundedRectangle(cornerRadius:13)).overlay(RoundedRectangle(cornerRadius:13).stroke(.cyan.opacity(0.18)))}.frame(maxWidth:.infinity,alignment:.leading)}
@MainActor private func ruleInfo(_ ref:CourseRuleReference,_ store:MaterialStore)->(String,String)?{guard let c=store.content(id:ref.materialID),let r=c.rules.first(where:{$0.id==ref.ruleID})else{return nil};return(c.material.title,ruleName(r,c))}
private func ruleName(_ r:QuestionRule,_ c:MaterialContent)->String{let f=Dictionary(uniqueKeysWithValues:c.fields.map{($0.key,$0.title)});let a=r.promptFieldKeys.compactMap{f[$0]}.joined(separator:" + ");let keys=Array(Set(r.answers.flatMap(\.fieldKeys)+[r.answerFieldKey])).filter{!$0.isEmpty};let b=keys.compactMap{f[$0]}.joined(separator:" + ");return !a.isEmpty && !b.isEmpty ? "\(a) → \(b)" : (r.kind == .card ? "Карточки":"Выбор ответа")}
private func time(_ m:Int)->String{m>=60 ? (m%60==0 ? "\(m/60) ч":"\(m/60) ч \(m%60) мин") : "\(m) мин"}
private struct SectionOrderView:View{@Binding var sections:[CourseSection];let onChange:()->Void;var body:some View{ZStack{CourseBG();List{Section{ForEach(Array(sections.enumerated()),id:\.element.id){i,s in HStack(spacing:14){Text(String(format:"%02d",i+1)).font(.headline).foregroundStyle(.black).frame(width:36,height:36).background(.cyan,in:Circle());VStack(alignment:.leading,spacing:3){Text(s.title).font(.headline).foregroundStyle(.white);Text("\(s.topics.count) тем").font(.caption2).foregroundStyle(.white.opacity(0.5))};Spacer()}.listRowBackground(Color(red:0.035,green:0.075,blue:0.14)).listRowSeparatorTint(.cyan.opacity(0.12))}.onMove{from,to in sections.move(fromOffsets:from,toOffset:to);onChange()}}header:{Text("ЗАЖМИТЕ ≡ И ПЕРЕТАЩИТЕ РАЗДЕЛ").font(.caption2.bold()).foregroundStyle(.cyan)}}.scrollContentBackground(.hidden).background(Color.clear).listStyle(.plain).contentMargins(.bottom,0,for:.scrollContent).environment(\.editMode,.constant(.active))}.navigationTitle("Порядок разделов").navigationBarTitleDisplayMode(.inline)}}
private struct TopicOrderView:View{@Binding var topics:[CourseTopic];let onChange:()->Void;var body:some View{ZStack{CourseBG();List{Section{ForEach(Array(topics.enumerated()),id:\.element.id){i,t in HStack(spacing:14){Text("\(i+1)").font(.headline).foregroundStyle(.cyan).frame(width:30,height:30).background(.cyan.opacity(0.1),in:Circle());VStack(alignment:.leading,spacing:3){Text(t.title).font(.headline).foregroundStyle(.white);Text("\(t.questionSets.count) опросников").font(.caption2).foregroundStyle(.white.opacity(0.5))};Spacer()}.listRowBackground(Color(red:0.035,green:0.075,blue:0.14)).listRowSeparatorTint(.cyan.opacity(0.12))}.onMove{from,to in topics.move(fromOffsets:from,toOffset:to);onChange()}}header:{Text("ЗАЖМИТЕ ≡ И ПЕРЕТАЩИТЕ ТЕМУ").font(.caption2.bold()).foregroundStyle(.cyan)}}.scrollContentBackground(.hidden).background(Color.clear).listStyle(.plain).contentMargins(.bottom,0,for:.scrollContent).environment(\.editMode,.constant(.active))}.navigationTitle("Порядок тем").navigationBarTitleDisplayMode(.inline)}}
private struct CourseBG:View{var body:some View{LinearGradient(colors:[Color(red:0.015,green:0.035,blue:0.12),Color(red:0.03,green:0.08,blue:0.18),.black],startPoint:.top,endPoint:.bottom).ignoresSafeArea()}}
private extension View{func card()->some View{background(.white.opacity(0.055),in:RoundedRectangle(cornerRadius:18)).overlay(RoundedRectangle(cornerRadius:18).stroke(.cyan.opacity(0.18)))}}
private extension String{var trim:String{trimmingCharacters(in:.whitespacesAndNewlines)}}
